function glossaryOf(term) {
  const q = term.trim().toLowerCase();
  if (!q) return void 0;
  return GLOSSARY.find(
    (e) => e.term.toLowerCase() === q || e.en.toLowerCase() === q || (e.aliases ?? []).some((a) => a.toLowerCase() === q)
  );
}

// ../hudi-visual-lab/src/experiments/visual/lesson-content.ts
function toGlossary(terms) {
  return terms.map((t) => {
    const entry = glossaryOf(t);
    return { term: entry?.term ?? t, def: entry?.def ?? t };
  });
}
